const C = ({ slug, term, title, seoTitle, seoDesc, short, body, ex, remember, quiz, lesson, related }) => ({
  slug, term, title: title || term, short, body, examples: ex, remember, quiz, lesson, related,
  seoTitle: seoTitle || `${term} — הסבר לילדים, עובדות וחידון`,
  seoDesc
})
const cloud = c => C({ ...c, lesson: 'cloud-types', seoTitle: c.seoTitle || `ענן ${c.term} — איך מזהים אותו ומה הוא מבשר` })
const rock = c => C({ ...c, lesson: c.lesson || 'rocks-of-israel', seoTitle: c.seoTitle || `${c.term} — איזה סלע זה, איך נוצר ואיפה מוצאים אותו` })
const mineral = c => C({ ...c, lesson: c.lesson || 'minerals-and-crystals', seoTitle: c.seoTitle || `${c.term} — מינרל: תכונות, קשיות ושימושים, לילדים` })
const gem = c => C({ ...c, lesson: 'gemstones', seoTitle: c.seoTitle || `${c.term} — אבן חן כמינרל: איך נוצרת וממה היא עשויה` })

